53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_YEARS_THRESHOLD = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
61	const INSURANCE_VALUES: Record<string, number> = {
62	  sword: 1000,
63	  amulet: 600,
64	  staff: 800,
65	  potion: 400,
66	  rune: 250,
67	  moonstone: 250,
68	};
69	
70	// Spec: an item's base premium is 10 % of its insurance value.
71	// Dividing by 10 (rather than multiplying by 0.1) keeps gold amounts
72	// exact in floating point.
73	const VALUE_TO_PREMIUM_RATIO = 10;
74	
75	const basePremiumOf = (itemType: string): number =>
76	  INSURANCE_VALUES[itemType] / VALUE_TO_PREMIUM_RATIO;
77	
78	const BLOCK_SIZE = 3;
79	const COMPONENT_BLOCK_PREMIUM = 60;
80	
81	const COMPONENT_TYPES = ["rune", "moonstone"];
82	
83	const componentBlockAdjustment = (
84	  items: Item[],
85	  componentType: string,
86	): number => {
87	  const count = items.filter((item) => item.type === componentType).length;
88	  return count === BLOCK_SIZE
89	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * basePremiumOf(componentType)
90	    : 0;
91	};
92	
93	const totalBasePremium = (items: Item[]): number =>
94	  items.reduce((total, item) => total + basePremiumOf(item.type), 0) +
95	  COMPONENT_TYPES.reduce(
96	    (total, componentType) => total + componentBlockAdjustment(items, componentType),
97	    0,
98	  );
99	
100	const surchargeFor = (
101	  items: Item[],
102	  rate: number,
103	  applies: (item: Item) => boolean,
104	): number =>
105	  items.reduce(
106	    (total, item) =>
107	      total + (applies(item) ? rate * basePremiumOf(item.type) : 0),
108	    0,
109	  );
110	
111	const isCursed = (item: Item): boolean => item.cursed === true;
112	
113	const isHighlyEnchanted = (item: Item): boolean =>
114	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
115	
116	const curseSurchargeFor = (items: Item[]): number =>
117	  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);
118	
119	const highEnchantmentSurchargeFor = (items: Item[]): number =>
120	  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
121	
122	const quotePremium = (
123	  items: Item[],
124	  customer: Customer,
125	  isFollowUpContract: boolean,
126	): number => {
127	  const basePremium = totalBasePremium(items);
128	  const itemSurcharges =
129	    curseSurchargeFor(items) + highEnchantmentSurchargeFor(items);
130	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
131	  const loyaltyDiscount =
132	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
133	      ? basePremium * LOYALTY_DISCOUNT_RATE
134	      : 0;
135	  const followUpDiscount = isFollowUpContract
136	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
137	    : 0;
138	  return Math.ceil(
139	    basePremium +
140	      itemSurcharges +
141	      firstInsuranceSurcharge -
142	      loyaltyDiscount -
143	      followUpDiscount +
144	      PROCESSING_FEE,
145	  );
146	};
147	
148	const DEDUCTIBLE_PER_DAMAGE = 100;
149	const PAYOUT_CAP_MULTIPLIER = 2;
150	const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
151	const REDUCED_REIMBURSEMENT_RATE = 0.5;
152	
153	// Spec: damage to items enchanted at 8 or above is reimbursed at 50 %
154	// (deductible is applied afterwards, per damage entry).
155	const reimbursementFor = (
156	  damage: Damage,
157	  damagedItem: Item | undefined,
158	): number =>
159	  (damagedItem?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
160	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
161	    : damage.amount;
162	
163	const initialCapFor = (policyItems: Item[]): number =>
164	  PAYOUT_CAP_MULTIPLIER *
165	  policyItems.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
166	
167	const settleClaim = (
168	  claimStep: ClaimStep,
169	  policyItems: Item[],
170	  remainingCapBefore: number,
171	): ClaimResult => {
172	  const uncappedPayout = claimStep.incident.damages.reduce((total, damage) => {
173	    const damagedItem = policyItems.find(
174	      (item) => item.type === damage.itemType,
175	    );
176	    return total + (reimbursementFor(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE);
177	  }, 0);
178	  const payout = Math.floor(Math.min(uncappedPayout, remainingCapBefore));
179	  return { payout, remainingCap: remainingCapBefore - payout };
180	};
181	
182	export const runScenario = (scenario: Scenario): ScenarioOutput => {
183	  const remainingCaps = new Map<number, number>();
184	  return {
185	    results: scenario.steps.map((step, index) => {
186	      if (step.op === "claim") {
187	        const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
188	        const capBefore =
189	          remainingCaps.get(step.policy) ?? initialCapFor(policyItems);
190	        const result = settleClaim(step, policyItems, capBefore);
191	        remainingCaps.set(step.policy, result.remainingCap);
192	        return result;
193	      }
194	      return {
195	        premium: quotePremium(step.items, scenario.customer, index > 0),
196	      };
197	    }),
198	  };
199	};
